{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.ubuntu[1]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance at index 1 is configured to have a public IP address, which increases the risk of unauthorized access. Public IPs should be avoided unless absolutely necessary."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 (IMDSv1) is less secure than IMDSv2 and is susceptible to SSRF attacks. It should be explicitly disabled in favor of IMDSv2."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not specify encryption for its root or additional EBS volumes. Unencrypted storage can lead to data exposure if the volume is compromised."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have an IAM role attached, which limits its ability to securely interact with AWS services without embedding credentials."
    }
  ],
  "patched_code": "resource "aws_instance" "ubuntu" {
  count = 3
  ami = data.aws_ami.ubuntu_14_04.image_id
  instance_type = "t2.micro"
  associate_public_ip_address = false
  subnet_id = aws_subnet.my_subnet.id

  metadata_options {
    http_tokens = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted = true
  }

  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "ec2_instance_profile"
  role = aws_iam_role.ec2_role.name
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ec2_policy" {
  name = "ec2_policy"
  role = aws_iam_role.ec2_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "s3:ListBucket"
        Resource = "arn:aws:s3:::example-bucket"
      }
    ]
  })
}",
  "fix_summary": "Removed public IP assignment for the second EC2 instance, enforced IMDSv2, enabled encryption for root EBS volumes, and attached an IAM role to the EC2 instances for secure AWS service access."
}
